-- 轻MES 数据库初始化脚本
-- 执行方式: mysql -uroot -p < init.sql

CREATE DATABASE IF NOT EXISTS light_mes DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE light_mes;

-- 用户表
CREATE TABLE IF NOT EXISTS sys_user (
  id            BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_name     VARCHAR(50)  NOT NULL UNIQUE COMMENT '登录名',
  password      VARCHAR(100) NOT NULL COMMENT 'BCrypt密码',
  real_name     VARCHAR(50)  COMMENT '姓名',
  phone         VARCHAR(20)  COMMENT '手机号',
  factory_code  VARCHAR(20)  COMMENT '所属工厂',
  enabled       TINYINT      DEFAULT 1 COMMENT '1启用 0禁用',
  create_time   DATETIME     DEFAULT CURRENT_TIMESTAMP
) COMMENT '用户表';

-- 菜单表
CREATE TABLE IF NOT EXISTS sys_menu (
  id        BIGINT PRIMARY KEY AUTO_INCREMENT,
  parent_id BIGINT       DEFAULT 0 COMMENT '父菜单ID，0为根',
  code      VARCHAR(50)  NOT NULL COMMENT '菜单编码',
  title     VARCHAR(50)  NOT NULL COMMENT '菜单名称',
  path      VARCHAR(100) COMMENT '前端路由',
  icon      VARCHAR(50)  COMMENT '图标名',
  sort      INT          DEFAULT 0 COMMENT '排序'
) COMMENT '菜单表';

-- 工厂表
CREATE TABLE IF NOT EXISTS factory (
  id      BIGINT PRIMARY KEY AUTO_INCREMENT,
  code    VARCHAR(20) NOT NULL UNIQUE COMMENT '工厂编码',
  name    VARCHAR(50) NOT NULL COMMENT '工厂名称',
  address VARCHAR(200)
) COMMENT '工厂表';

-- 生产加工单主表
CREATE TABLE IF NOT EXISTS manu_order (
  id            BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_no      VARCHAR(30)  NOT NULL UNIQUE COMMENT '单号',
  order_date    DATE         COMMENT '单据日期',
  factory_code  VARCHAR(20)  COMMENT '工厂编码',
  contract_no   VARCHAR(50)  COMMENT '合同号',
  ingot_no      VARCHAR(50)  COMMENT '锭号',
  batch_no      VARCHAR(50)  COMMENT '批号（如：正常/加急）',
  workshop      VARCHAR(50)  COMMENT '生产车间',
  plan_start    DATE         COMMENT '预开工日',
  plan_end      DATE         COMMENT '预完工日',
  sale_order_no VARCHAR(50)  COMMENT '销售订单号',
  customer_code VARCHAR(50)  COMMENT '客户编码',
  customer_name VARCHAR(100) COMMENT '客户',
  test_program  VARCHAR(100) COMMENT '测试程序',
  prod_order_customer VARCHAR(100) COMMENT '生产订单客户',
  status        TINYINT      DEFAULT 0 COMMENT '状态 0草稿 1已审核 2生产中 3已完工 4已关闭',
  remark        VARCHAR(500) COMMENT '备注',
  create_by     VARCHAR(50)  COMMENT '制单人',
  create_time   DATETIME     DEFAULT CURRENT_TIMESTAMP COMMENT '制单时间',
  audit_by      VARCHAR(50)  COMMENT '审核人',
  audit_time    DATETIME     COMMENT '审核时间',
  close_time    DATETIME     COMMENT '关闭时间'
) COMMENT '生产加工单主表';

-- 生产加工单工序分录
CREATE TABLE IF NOT EXISTS manu_order_item (
  id            BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_id      BIGINT NOT NULL COMMENT '主表ID',
  seq           INT    DEFAULT 1 COMMENT '序号',
  process_code  VARCHAR(50)  COMMENT '工序编码',
  process_name  VARCHAR(100) COMMENT '工序名称',
  equipment     VARCHAR(100) COMMENT '设备',
  worker_group  VARCHAR(50)  COMMENT '班组',
  plan_qty      DECIMAL(18,4) DEFAULT 0 COMMENT '计划数量',
  finished_qty  DECIMAL(18,4) DEFAULT 0 COMMENT '完工数量',
  qualified_qty DECIMAL(18,4) DEFAULT 0 COMMENT '合格数量',
  defect_qty    DECIMAL(18,4) DEFAULT 0 COMMENT '不良数量',
  start_time    DATETIME     COMMENT '开工时间',
  end_time      DATETIME     COMMENT '完工时间',
  remark        VARCHAR(200) COMMENT '备注'
) COMMENT '生产加工单工序分录';

-- ===== 元数据驱动表单引擎（自研类 PanelX，不依赖外部平台）=====

-- 面板配置表（字段/表格列/按钮/状态选项/明细定义 全部 JSON 化）
CREATE TABLE IF NOT EXISTS panel_config (
  id          BIGINT PRIMARY KEY AUTO_INCREMENT,
  panel_code  VARCHAR(50)  NOT NULL UNIQUE COMMENT '面板编码',
  panel_name  VARCHAR(100) COMMENT '面板名称',
  category    VARCHAR(50)  COMMENT '分类',
  config      TEXT         COMMENT '面板配置JSON（metadata+dataSchema+detail）',
  version     VARCHAR(10)  DEFAULT '1.0',
  create_time DATETIME     DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) COMMENT '面板配置表';

-- 表单数据表（表头/明细 JSON 动态存储，不按面板建表）
CREATE TABLE IF NOT EXISTS form_data (
  id          BIGINT PRIMARY KEY AUTO_INCREMENT,
  panel_code  VARCHAR(50)  NOT NULL COMMENT '面板编码',
  form_no     VARCHAR(50)  COMMENT '编号',
  data        TEXT         COMMENT '表单表头JSON',
  detail_data TEXT         COMMENT '明细分录JSON',
  status      VARCHAR(20)  DEFAULT '草稿' COMMENT '单据状态',
  create_by   VARCHAR(50)  COMMENT '制单人',
  create_time DATETIME     DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  audit_by    VARCHAR(50)  COMMENT '审核人',
  audit_time  DATETIME     COMMENT '审核时间',
  close_time  DATETIME     COMMENT '关闭时间',
  KEY idx_panel_no (panel_code, form_no)
) COMMENT '表单数据表';

